target.css:
:root {
  --ink: #26322a;
  --muted: #6d786b;
  --paper: #fffdf6;
  --cream: #f7f1df;
  --line: #ded7c4;
  --amber: #d8901f;
  --amber-soft: #fff0bf;
  --leaf: #376b4d;
  --leaf-soft: #e1efe4;
  --coral: #c75d45;
}

.hive-board,
.hive-board * {
  box-sizing: border-box;
}

.hive-board {
  width: 500px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.board-header,
.hive-mark,
.hive-overview,
.inspection-title,
.board-footer,
.queen-card,
.check-list,
.action {
  display: flex;
  align-items: center;
}

.board-header,
.inspection-title,
.board-footer {
  justify-content: space-between;
}

.board-header {
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.hive-mark {
  gap: 10px;
}

.hive-icon {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 10px;
  background: var(--amber-soft);
  color: var(--amber);
  font-size: 24px;
  line-height: 1;
}

.hive-mark hgroup,
.hive-mark h1,
.hive-mark p,
.queen-card p,
.inspection-title h2,
.inspection-title p,
.board-footer p {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

.hive-mark h1 {
  margin-top: 3px;
  font-size: 18px;
  line-height: 1.1;
}

.health-pill,
.date-tag {
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.health-pill {
  padding: 6px 9px;
  background: var(--leaf-soft);
  color: var(--leaf);
}

.hive-overview {
  gap: 12px;
  padding: 12px 0;
}

.queen-card {
  width: 185px;
  min-height: 62px;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--cream);
}

.queen-icon {
  display: grid;
  width: 35px;
  height: 35px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 50%;
  background: var(--amber);
  color: var(--paper);
  font-size: 18px;
}

.queen-card strong {
  display: block;
  margin: 2px 0;
  font-size: 13px;
  line-height: 1.1;
}

.queen-note {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.15;
}

.metric-grid {
  display: grid;
  flex: 1;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: 0;
}

.metric {
  padding: 9px 7px;
  border-left: 1px solid var(--line);
}

.metric dt {
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.metric dd {
  margin: 0;
  font-size: 19px;
  font-weight: 800;
  line-height: 1;
}

.metric dd span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.alert-metric dd {
  color: var(--coral);
}

.inspection-panel {
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--cream);
}

.inspection-title h2 {
  margin-top: 2px;
  font-size: 14px;
  line-height: 1.15;
}

.date-tag {
  padding: 5px 7px;
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--muted);
}

.check-list {
  gap: 13px;
  margin: 9px 0 0;
  padding: 0;
  list-style: none;
  color: var(--ink);
  font-size: 11px;
  font-weight: 600;
}

.check-list li {
  display: flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}

.check {
  display: grid;
  width: 16px;
  height: 16px;
  place-items: center;
  border-radius: 5px;
  background: var(--leaf);
  color: var(--paper);
  font-size: 11px;
  line-height: 1;
}

.board-footer {
  padding-top: 11px;
}

.board-footer p {
  color: var(--muted);
  font-size: 12px;
}

.board-footer strong {
  color: var(--ink);
}

.action {
  gap: 8px;
  padding: 8px 11px;
  border: 0;
  border-radius: 9px;
  background: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
}

.action span {
  color: var(--amber);
  font-size: 16px;
}

